#!/usr/bin/env python3
"""Run C2 Unit05 recalibration with target-safe C2 length margin."""
from pathlib import Path
SOURCE=Path(__file__).with_name('recalibrate_final_arabic_c2_unit05.py')
text=SOURCE.read_text(encoding='utf-8')
marker='UPDATES={'
assert text.count(marker)==1
EXTRA={
'ar-c2-u05-p01':"""وفي تمرين أخير أعطت الناقدة الطلاب فقرة واحدة من دون سياق، ثم كشفت لهم لاحقًا أن الفاعل كان موضع اتهام في الفقرة السابقة. تغيّر تفسيرهم لتقديم السبب وإخفاء صاحب الفعل، ما أكد أن الأثر لا يسكن الصياغة وحدها. طلبت منهم إعادة التحليل مع بيان ما أضافه السياق بدل محو القراءة الأولى. صار التقرير يميز بين أثر يمكن رصده من العبارة نفسها وأثر يعتمد على معرفة سابقة لدى القارئ. هذا الفصل منعهم من نسبة كل قوة إلى ترتيب الكلمات، وأظهر أن القراءة الدقيقة تحتاج إلى خريطة لما يعرفه المتلقي قبل كل لحظة من النص.""",
'ar-c2-u05-p02':"""وفي مراجعة مستقلة استمع فريق آخر إلى نسختين من المقطع من دون معرفة هدف التجربة. وصفوا في إحداهما حركة أسرع ونهاية أكثر اتساعًا، وهي ملاحظات قريبة من التحليل النصي السابق. لم تعامل الناقدة الاتفاق كبرهان نهائي، لكنه أعطاها سببًا إضافيًا للاعتقاد أن الفرق ليس اختراعًا فرديًا. ثم طلبت من الفريق تحديد الموضع الذي بدأ عنده التغير بدل اختيار صفات عامة. عندما تقاربت الإجابات حول الكسر الأخير، أصبح من الممكن ربط الاستجابة بعنصر محدد في الشكل لا بانطباع شامل عن جمال القطعة.""",
'ar-c2-u05-p03':"""وفي مراجعة عمياء أعطى المدرس القرائن نفسها لمجموعة لم تقرأ بقية القصة، ثم أعطاها السياق السابق على دفعتين. في كل مرحلة كتب المشاركون أكثر تأويلين يريان أنهما مدعومان. تضيق مجموعة البدائل كلما ظهرت مادة ذات صلة، لكن بعض الاحتمالات ظلت مفتوحة. استخدم المدرس هذا التغير لإظهار أن القراءة الجيدة يمكن أن تزيد ثقتها تدريجيًا من دون ادعاء يقين كامل. المهم أن يستطيع القارئ ذكر العلامة التي رفعت وزن تفسير وخفضت وزن آخر، وأن يترك الاحتمال قائمًا حين لا توجد مادة تكفي لحسمه.""",
'ar-c2-u05-p04':"""وفي اختبار إضافي غيّر الفريق ترتيب المعلومات من دون تغيير حجم الخط، ثم غيّر الحجم من دون تغيير الترتيب. انخفض سوء الفهم في الحالتين لكن بدرجات مختلفة، ما أظهر أن البروز ليس خاصية واحدة. الموضع والزمن البصري والتباين كلها قد تسهم. صمموا نسخة تجمع التحسينين ثم سألوا المشاركين عن السياسة بكلماتهم الخاصة قبل عرض خيارات جاهزة، حتى لا تقود صيغة السؤال إلى الإجابة. ساعد ذلك على التحقق من أن الفهم الصحيح نشأ من العرض نفسه لا من قدرة المشارك على اختيار العبارة الأقرب من قائمة بعدية.""",
'ar-c2-u05-p05':"""وفي مراجعة أخيرة طلبت اللجنة من الباحث أن يسجل خلاصة من ستين ثانية ثم خلاصة من عشر دقائق. كان عليه أن يحافظ في النسختين على النطاق نفسه وعلى الفرق بين النتيجة المباشرة والتفسير. نجح الاختبار عندما استطاع المراجعون إعادة صياغة الحدود الأساسية بعد كل نسخة رغم اختلاف مقدار التفاصيل. أظهر ذلك أن الاختصار الجيد لا يقاس بعدد الكلمات المحذوفة، بل بما إذا كانت البنية المعرفية التي تحد قوة الادعاء ما تزال قابلة للاسترجاع. إذا احتفظ الجمهور بالنهاية ونسي الشرط الذي يجعلها صحيحة، فقد خسر العرض جزءًا من الحجة حتى لو ظل جذابًا وسهل التذكر.""",
'ar-c2-u05-p06':"""وفي مراجعة نهائية جمع الطلاب تحليلاتهم في جدول من أربعة أعمدة: القرار الشكلي، والأثر المتوقع، والدليل الذي يربطهما، والبديل الذي قد يفسر الأثر نفسه. أجبرهم العمود الأخير على مقاومة الثقة السريعة؛ فقد يكون ما يبدو أثرًا للترتيب ناتجًا أيضًا من طول العبارة أو من معرفة سابقة. ثم طلبت الناقدة اختبار البدائل بمقارنة إضافية كلما أمكن. لا يحتاج النقد إلى تجربة مخبرية كاملة، لكنه يستفيد من المنطق نفسه: افصل ما تستطيع، اذكر ما لم تستطع فصله، ولا تجعل الوصف اللامع بديلاً عن بيان العلاقة التي يمكن لقارئ آخر أن يفحصها.""",
}
extra_code="EXTRA = "+repr(EXTRA)+"\nfor _pid,_extra in EXTRA.items():\n    ADD[_pid]=ADD[_pid].rstrip()+' '+_extra.strip()\n"
patched=text.replace(marker,extra_code+'\n'+marker,1)
exec(compile(patched,str(SOURCE),'exec'),{'__name__':'__main__','__file__':str(SOURCE)})
